ons":"","adjustability":"","footprint":null,"space":"S","price_band":"$","requires":["pool"],"substitutes":[],"signature_exercises":["Kickboard kick sets","Pull buoy freestyle","Paddle sets","Fin drills"],"exercise_ids":["swimfree"],"buying_tips":"Start with small paddles to protect the shoulders.","safety":"Build up paddle use gradually."},{"id":"deskelliptic","name":"Under-desk elliptical","aliases":["Seated elliptical","Cubii"],"keywords":"under desk seated elliptical cubii","category":"Elliptical & gliders","subcategory":"Compact ellipticals","app_group":"Cardio","group_order":7,"sort_order":26,"tier":1,"setting":"home","description":"A small pedal-only elliptical you use seated under a desk or chair, for gentle leg movement during the day.","muscle_focus":["Quads","Calves","Glutes"],"loading":"Air / magnetic / fan resistance","weight_options":"Magnetic, ~8 levels","adjustability":"Resistance dial; some motorised.","footprint":{"length_cm":60,"width_cm":45,"height_cm":25},"space":"S","price_band":"$$","requires":[],"substitutes":["pedalexer","ministepper"],"signature_exercises":["Seated elliptical pedalling","Under-desk cycling","Reverse pedalling"],"exercise_ids":[],"buying_tips":"Low and quiet; check your desk height leaves enough knee room.","safety":""},{"id":"walkingpad","name":"Walking pad","aliases":["Under-desk treadmill","Folding treadmill","Walking treadmill"],"keywords":"under desk walking pad folding","category":"Treadmills","subcategory":"Compact treadmills","app_group":"Cardio","group_order":7,"sort_order":27,"tier":1,"setting":"home","description":"A slim, low, often folding treadmill without handrails, mostly for walking at a desk or in small spaces.","muscle_focus":["Heart & lungs","Calves","Glutes"],"loading":"Motorised","weight_options":"Top speed 6–12 km/h; usually no incline","adjustability":"Speed by remote or app; folds or slides under a sofa.","footprint":{"length_cm":140,"width_cm":55,"height_cm":15},"space":"M","price_band":"$$","requires":[],"substitutes":["treadmill"],"signature_exercises":["Treadmill walk","Desk walking","Brisk walking intervals"],"exercise_ids":["treadwalk"],"buying_tips":"Check top speed and belt width; most are not built for running even if they claim a running mode.","safety":"Keep the speed low enough to walk without holding on, as there are usually no rails."},{"id":"nordicski","name":"Cross-country ski machine","aliases":["NordicTrack ski machine","Ski machine"],"keywords":"nordictrack ski machine cross country","category":"Elliptical & gliders","subcategory":"Gliders","app_group":"Cardio","group_order":7,"sort_order":28,"tier":2,"setting":"home","description":"A machine with sliding foot skis and pull cords for the arms, copying classic cross-country skiing for full-body cardio.","muscle_focus":["Heart & lungs","Quads","Glutes","Lats","Triceps"],"loading":"Friction","weight_options":"Friction flywheel and arm cord tension","adjustability":"Leg and arm resistance separately; incline.","footprint":{"length_cm":200,"width_cm":60,"height_cm":120},"space":"L","price_band":"$$$","requires":[],"substitutes":["skierg","elliptical"],"signature_exercises":["Classic ski stride","Arm-and-leg intervals","Legs-only ski stride"],"exercise_ids":[],"buying_tips":"Mostly second-hand now; takes practice to coordinate arms and legs.","safety":""},{"id":"inclinetrainer","name":"Incline trainer","aliases":["Incline treadmill","X-trainer"],"keywords":"incline hill walk hiking","category":"Treadmills","subcategory":"Motorised treadmills","app_group":"Cardio","group_order":7,"sort_order":29,"tier":2,"setting":"both","description":"A treadmill built for steep uphill walking, often up to 30–40% incline and some with decline, for hiking-style cardio.","muscle_focus":["Heart & lungs","Glutes","Hamstrings","Calves"],"loading":"Motorised","weight_options":"Incline up to 30–40%; decline to −6% on some","adjustability":"Speed and steep incline by console.","footprint":{"length_cm":200,"width_cm":90,"height_cm":160},"space":"L","price_band":"$$$$","requires":[],"substitutes":["treadmill","stairs"],"signature_exercises":["Incline treadmill walk","12-3-30 workout","Hill intervals","Treadmill walk"],"exercise_ids":["w12330","inclinewalk","treadint","treadwalk"],"buying_tips":"Worth it if you mostly walk; check the incline motor speed and that the deck stays stable at maximum incline.","safety":"Don't hold the rails at steep inclines; slow down instead."},{"id":"smartbike","name":"Smart bike","aliases":["Peloton","Wahoo KICKR Bike","Zwift Ride","Connected bike"],"keywords":"peloton smart zwift connected bike","category":"Bikes","subcategory":"Indoor cycles","app_group":"Cardio","group_order":7,"sort_order":31,"tier":2,"setting":"home","description":"A connected indoor bike with automatic, app-controlled resistance, power measurement and often a screen for classes or virtual rides.","muscle_focus":["Heart & lungs","Quads","Glutes","Calves"],"loading":"Air / magnetic / fan resistance","weight_options":"Electromagnetic, power to 1,500–2,500 W","adjustability":"Resistance set by app; fit adjusts to a road bike.","footprint":{"length_cm":130,"width_cm":60,"height_cm":140},"space":"M","price_band":"$$$$","requires":[],"substitutes":["spinbike","turbotrainer"],"signature_exercises":["Power-based intervals","Virtual climbs","FTP test","Spin class ride"],"exercise_ids":["spinint","bikeride","tabatabike"],"buying_tips":"Check which apps it works with and whether a subscription is required to use the resistance features.","safety":""},{"id":"stepper","name":"Step machine","aliases":["Stair stepper","Pedal stepper","StairMaster 4000 PT"],"keywords":"stepper stair pedals","category":"Steppers & climbers","subcategory":"Pedal steppers","app_group":"Cardio","group_order":7,"sort_order":32,"tier":2,"setting":"both","description":"A machine with two independent pedals you press down in turn, like climbing stairs without leaving the spot.","muscle_focus":["Heart & lungs","Glutes","Quads","Calves"],"loading":"Hydraulic","weight_options":"Hydraulic or magnetic, 10–20 levels","adjustability":"Resistance and step depth.","footprint":{"length_cm":120,"width_cm":75,"height_cm":160},"space":"M","price_band":"$$$","requires":[],"substitutes":["stairs","ministepper"],"signature_exercises":["Stepper intervals","Steady stepping","Deep-step glute climb"],"exercise_ids":["stair"],"buying_tips":"Look for independent pedals and a solid frame; cheap ones feel bouncy.","safety":""},{"id":"waterrower","name":"Water rower","aliases":["WaterRower","Hydro rower"],"keywords":"water rower wooden","category":"Rowers & ergs","subcategory":"Water rowers","app_group":"Cardio","group_order":7,"sort_order":33,"tier":2,"setting":"home","description":"A rowing machine whose resistance comes from paddles in a tank of water, giving a smooth, quiet, boat-like feel.","muscle_focus":["Heart & lungs","Quads","Glutes","Upper back","Lats","Arms"],"loading":"Friction","weight_options":"Resistance set by water level","adjustability":"Water level; folds upright.","footprint":{"length_cm":210,"width_cm":55,"height_cm":55},"space":"L","price_band":"$$$","requires":[],"substitutes":["rower","magrower"],"signature_exercises":["Steady-state row","Rowing intervals","2,000 m row"],"exercise_ids":["row2k","rowint","row"],"buying_tips":"Looks good and stands upright for storage; numbers differ from a Concept2, so don't compare splits.","safety":""},{"id":"antigravtread","name":"Anti-gravity treadmill","aliases":["AlterG","Unweighting treadmill","Lower-body positive pressure treadmill"],"keywords":"alterg rehab unweighted running","category":"Treadmills","subcategory":"Rehab treadmills","app_group":"Cardio","group_order":7,"sort_order":34,"tier":3,"setting":"commercial","description":"A treadmill inside an air-pressurised chamber that lifts part of your body weight, used in rehab and for low-impact running.","muscle_focus":["Heart & lungs","Quads","Glutes","Hamstrings","Calves"],"loading":"Motorised","weight_options":"Body weight unloading 20–100%","adjustability":"Air pressure sets how much body weight you carry.","footprint":{"length_cm":210,"width_cm":90,"height_cm":140},"space":"XL","price_band":"$$$$","requires":[],"substitutes":["treadmill"],"signature_exercises":["Unweighted treadmill run","Return-to-run progression","Unweighted walk"],"exercise_ids":["treadrun","treadwalk"],"buying_tips":"Found in physio clinics and pro sports facilities; pay per session rather than buying.","safety":"Follow your physio's progression plan for body-weight percentage."},{"id":"arctrainer","name":"Arc trainer","aliases":["Cybex Arc Trainer"],"keywords":"arc trainer cybex","category":"Elliptical & gliders","subcategory":"Ellipticals","app_group":"Cardio","group_order":7,"sort_order":35,"tier":3,"setting":"commercial","description":"An elliptical-like machine with an arc-shaped foot path and high incline, putting more load on the glutes with less knee stress.","muscle_focus":["Heart & lungs","Glutes","Quads","Hamstrings"],"loading":"Air / magnetic / fan resistance","weight_options":"Resistance and incline levels","adjustability":"Incline and resistance.","footprint":{"length_cm":190,"width_cm":80,"height_cm":170},"space":"L","price_band":"$$$$","requires":[],"substitutes":["elliptical","stairs"],"signature_exercises":["Arc trainer intervals","High-incline climb","Steady low-impact cardio"],"exercise_ids":["ellip"],"buying_tips":"Mostly found in commercial gyms; try different incline settings to shift work to the glutes.","safety":""},{"id":"bikeerg","name":"BikeErg","aliases":["Concept2 BikeErg","Fan bike erg"],"keywords":"bikeerg concept2 bike erg","category":"Rowers & ergs","subcategory":"Bike ergs","app_group":"Cardio","group_order":7,"sort_order":36,"tier":3,"setting":"both","description":"Concept2's fan-resistance indoor bike with the same monitor as their rower, used for comparable, measurable bike work.","muscle_focus":["Heart & lungs","Quads","Glutes","Calves"],"loading":"Air / magnetic / fan resistance","weight_options":"Air fan with damper 1–10","adjustability":"Seat and bar height; road-bike fit.","footprint":{"length_cm":120,"width_cm":60,"height_cm":120},"space":"M","price_band":"$$$","requires":[],"substitutes":["spinbike","airbike"],"signature_exercises":["BikeErg intervals","Calorie sprints","Tabata bike","Steady-state ride"],"exercise_ids":["spinint","bikeride","tabatabike"],"buying_tips":"Accepts your own saddle and pedals; very low upkeep compared with friction spin bikes.","safety":""},{"id":"jacobsladder","name":"Jacob's ladder","aliases":["Ladder climber","Endless ladder"],"keywords":"jacobs ladder climbing","category":"Steppers & climbers","subcategory":"Vertical climbers","app_group":"Cardio","group_order":7,"sort_order":37,"tier":3,"setting":"commercial","description":"An endless sloped ladder you climb on all fours; it moves at the speed you climb, for self-paced full-body cardio.","muscle_focus":["Heart & lungs","Glutes","Quads","Shoulders","Core"],"loading":"None (support/tool)","weight_options":"Self-paced","adjustability":"Speed set by your climbing; hip belt.","footprint":{"length_cm":210,"width_cm":90,"height_cm":230},"space":"L","price_band":"$$$$","requires":[],"substitutes":["versaclimber","stairs"],"signature_exercises":["Ladder climb intervals","Steady climb","Calorie sprints"],"exercise_ids":[],"buying_tips":"Mostly seen in CrossFit and military-style gyms; needs a high ceiling.","safety":"Wear the hip belt so you can't climb off the top."},{"id":"lateraltrainer","name":"Lateral trainer","aliases":["Octane LateralX","Lateral elliptical","Stride trainer","Precor AMT"],"keywords":"lateral x elliptical stride amt","category":"Elliptical & gliders","subcategory":"Ellipticals","app_group":"Cardio","group_order":7,"sort_order":38,"tier":3,"setting":"commercial","description":"An elliptical that adds side-to-side motion to the stride, training the hips and inner and outer thighs.","muscle_focus":["Hear