ard"],"keywords":"mouthguard gumshield","category":"Combat","subcategory":"Protective gear","app_group":"Combat","group_order":10,"sort_order":10,"tier":1,"setting":"both","description":"A shaped guard over the teeth to protect them and the jaw during sparring and contact.","muscle_focus":[],"loading":"None (support/tool)","weight_options":"Boil-and-bite or custom","adjustability":"Mouldable.","footprint":null,"space":"S","price_band":"$","requires":[],"substitutes":[],"signature_exercises":["Sparring","Grappling","Contact drills"],"exercise_ids":[],"buying_tips":"Boil-and-bite is fine to start; custom-fit is worth it for regular sparring.","safety":"Wear one for any contact sparring."},{"id":"reflexbag","name":"Reflex bag","aliases":["Reflex ball stand","Spinning reflex bar","Boxing reflex ball"],"keywords":"reflex bag ball stand","category":"Combat","subcategory":"Bags","app_group":"Combat","group_order":10,"sort_order":11,"tier":1,"setting":"home","description":"A ball or pad on a spring-loaded stand (or headband) that rebounds quickly for speed and reaction drills.","muscle_focus":["Shoulders","Arms"],"loading":"Spring","weight_options":"Stand 120–170 cm","adjustability":"Height adjustable.","footprint":{"length_cm":50,"width_cm":50,"height_cm":160},"space":"S","price_band":"$$","requires":[],"substitutes":["doubleend","speedbag"],"signature_exercises":["Reflex ball punches","Jab and slip","Rapid combinations"],"exercise_ids":[],"buying_tips":"A weighted base that doesn't tip matters more than the ball.","safety":""},{"id":"shinguards","name":"Shin guards","aliases":["Shin pads","Shin and instep guards"],"keywords":"shin guards pads","category":"Combat","subcategory":"Protective gear","app_group":"Combat","group_order":10,"sort_order":12,"tier":1,"setting":"both","description":"Padded guards covering the shin and instep for kicking pads, bags and sparring partners.","muscle_focus":["Legs"],"loading":"None (support/tool)","weight_options":"S–XL","adjustability":"