,"primary_muscles":["Glutes","Hamstrings"],"secondary_muscles":["Lower back"],"movement_pattern":"Hinge","equipment":["Reverse hyper machine"],"req":"reversehyper","equipment_tier":3,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":3,"reps":"12–15","form_cues":["Lie chest-down with hips at the pad's edge and grip the handles.","Swing legs up until in line with the body, squeezing glutes.","Lower under control; don't let the pendulum yank you."],"common_mistakes":["Letting momentum drive the swing.","Overarching at the top."],"regressions":["Glute bridge"],"progressions":["GHD hip extension"],"safety":"Start light; the strap and pendulum can whip the spine if you go too heavy.","video":null,"diagram":"","notes":"Popular as a lower-back rehab and strength accessory."},{"id":"parapush","name":"Parallette push-up","aliases":["Deep push-up"],"training_type":"Calisthenics","tags":["Calisthenics","Home-friendly","Strength"],"muscle_group":"Chest","primary_muscles":["Chest","Triceps"],"secondary_muscles":["Front delts","Core"],"movement_pattern":"Horizontal push","equipment":["Parallettes"],"req":"parallettes","equipment_tier":1,"difficulty":"Intermediate","tracking":"bw","unilateral":false,"sets":3,"reps":"8–12","form_cues":["Grip parallettes under your shoulders in a push-up.","Lower your chest below hand height for extra range.","Press back up to straight arms."],"common_mistakes":["Going deeper than shoulders tolerate","Sagging hips"],"regressions":["Push-ups"],"progressions":["Pseudo planche push-up"],"safety":"Make sure the parallettes are on a non-slip surface.","video":null,"diagram":"","notes":"Neutral grip is easy on the wrists."},{"id":"humanflag","name":"Human flag","aliases":["Flag"],"training_type":"Calisthenics","tags":["Calisthenics","Core","Strength"],"muscle_group":"Shoulders","primary_muscles":["Lats","Obliques","Shoulders"],"secondary_muscles":["Core","Triceps","Grip"],"movement_pattern":"Hold","equipment":["Vertical pole or stall bars"],"req":"pole|stallbars","equipment_tier":1,"difficulty":"Advanced","tracking":"hold","unilateral":false,"sets":4,"reps":"3–10 sec","form_cues":["Grip a vertical pole with hands wide, top arm pulling, bottom arm pushing.","Lock both arms and lift your body sideways.","Hold your legs level with the floor."],"common_mistakes":["Bending the bottom arm","Hips sagging"],"regressions":["Tuck human flag","Side plank"],"progressions":[],"safety":"Use a fixed pole that cannot rotate; warm up shoulders well.","video":null,"diagram":"","notes":"No exact gear id for a vertical pole; pullupbar used as nearest."},{"id":"ringdip","name":"Ring dip","aliases":[],"training_type":"Calisthenics","tags":["Calisthenics","Compound","Strength"],"muscle_group":"Chest","primary_muscles":["Chest","Triceps"],"secondary_muscles":["Front delts","Core","Biceps"],"movement_pattern":"Vertical push","equipment":["Gymnastic rings"],"req":"rings","equipment_tier":2,"difficulty":"Advanced","tracking":"bw","unilateral":false,"sets":3,"reps":"4–8","form_cues":["Start in a stable ring support.","Lower until shoulders are below elbows, rings close to the body.","Press back up and turn rings out at the top."],"common_mistakes":["Rings flaring wide","Too deep too soon"],"regressions":["Chest dips","Ring support hold"],"progressions":["Ring muscle-up"],"safety":"Master ring support holds first; instability is high.","video":null,"diagram":"","notes":""},{"id":"ringpush","name":"Ring push-ups","aliases":[],"training_type":"Calisthenics","tags":["Calisthenics","Compound","Strength"],"muscle_group":"Chest","primary_muscles":["Chest","Triceps"],"secondary_muscles":["Front delts","Core","Serratus anterior"],"movement_pattern":"Horizontal push","equipment":["Gymnastic rings"],"req":"rings","equipment_tier":2,"difficulty":"Intermediate","tracking":"bw","unilateral":false,"sets":3,"reps":"6–12","form_cues":["Set rings a few centimetres off the floor and grip them.","Lower with rings close to your sides.","Press up and turn rings out slightly at the top."],"common_mistakes":["Rings drifting apart","Sagging hips"],"regressions":["Push-ups"],"progressions":["Ring dip","Ring fly"],"safety":"Start with rings higher to reduce the instability.","video":null,"diagram":"pushup","notes":""},{"id":"ironcross","name":"Iron cross","aliases":["Cross"],"training_type":"Calisthenics","tags":["Calisthenics","Strength"],"muscle_group":"Back","primary_muscles":["Lats","Chest"],"secondary_muscles":["Biceps","Shoulders","Core"],"movement_pattern":"Hold","equipment":["Gymnastic rings"],"req":"rings","equipment_tier":2,"difficulty":"Advanced","tracking":"hold","unilateral":false,"sets":4,"reps":"2–5 sec","form_cues":["Start from ring support and spread arms out to the sides.","Keep arms straight and press rings down.","Hold the T shape with body upright."],"common_mistakes":["Bending elbows","Dropping below horizontal"],"regressions":["Ring fly"],"progressions":[],"safety":"Elite gymnastics skill; high tendon load, train with bands and spotting.","video":null,"diagram":"","notes":""},{"id":"ringmu","name":"Ring muscle-up","aliases":[],"training_type":"Calisthenics","tags":["Calisthenics","Power","Strength"],"muscle_group":"Back","primary_muscles":["Lats","Chest","Triceps"],"secondary_muscles":["Biceps","Core","Shoulders"],"movement_pattern":"Vertical pull","equipment":["Gymnastic rings"],"req":"rings","equipment_tier":2,"difficulty":"Advanced","tracking":"bw","unilateral":false,"sets":3,"reps":"1–5","form_cues":["Hang using a false grip.","Pull rings to the chest and lean the shoulders forward over them.","Transition into a dip and press to support."],"common_mistakes":["Losing the false grip","Pulling too far away from the rings"],"regressions":["Ring dip","Chest-to-bar pull-up"],"progressions":[],"safety":"Build strong ring dips and false-grip pull-ups first.","video":null,"diagram":"","notes":""},{"id":"ringsupport","name":"Ring support hold","aliases":["RTO support"],"training_type":"Calisthenics","tags":["Calisthenics","Strength"],"muscle_group":"Arms","primary_muscles":["Triceps","Shoulders"],"secondary_muscles":["Chest","Biceps","Core"],"movement_pattern":"Hold","equipment":["Gymnastic rings"],"req":"rings","equipment_tier":2,"difficulty":"Intermediate","tracking":"hold","unilateral":false,"sets":3,"reps":"15–30 sec","form_cues":["Jump up to support on the rings with straight arms.","Keep rings close to your hips.","Turn the rings out so palms face forward if you can."],"common_mistakes":["Rings swaying out","Shrugging"],"regressions":["Dip support hold"],"progressions":["Ring dip","Ring L-sit"],"safety":"Use a box to get in and out.","video":null,"diagram":"","notes":""},{"id":"landminerot","name":"Landmine rotation","aliases":["Landmine 180","Landmine rainbow","Landmine twist"],"training_type":"Core","tags":["Core","Power"],"muscle_group":"Core","primary_muscles":["Obliques"],"secondary_muscles":["Shoulders","Rectus abdominis","Glutes"],"movement_pattern":"Rotation","equipment":["Barbell","Landmine attachment"],"req":"landmine,barbell","equipment_tier":2,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":3,"reps":"8–10 / side","form_cues":["Hold the bar end at arm's length above your head","Rotate it down in an arc to one hip, pivoting the feet","Bring it back over the top and go to the other side"],"common_mistakes":["Bending the arms","Twisting from the lower back with locked hips"],"regressions":["Russian twist","Cable woodchop"],"progressions":["Heavier landmine rotation"],"safety":"Start with the empty bar; use a corner if you have no landmine.","video":null,"diagram":"","notes":""},{"id":"ghdsitup","name":"GHD sit-up","aliases":["Glute-ham developer sit-up"],"training_type":"Core","tags":["Core"],"muscle_group":"Core","primary_muscles":["Rectus abdominis","Hip flexors"],"secondary_muscles":["Quadriceps","Obliques"],"movement_pattern":"Flexion","equipment":["Glute-ham developer"],"req":"ghd","equipment_tier":3,"difficulty":"Advanced","tracking":"bw","unilateral":false,"sets":3,"reps":"8–15","form_cues":["Sit on the pad with feet locked, hips just past it","Lower back to parallel, then reach behind if trained","Kick the knees straight to sit up and reach for your feet"],"common_mistakes":["Going too far back too soon","Doing high volume on the first try"],"regressions":["Decline sit-up"],"progressions":[],"safety":"Start with low reps and a short range; overuse can cause rhabdo or back strain.","video":null,"diagram":"","notes":""},{"id":"parachute","name":"Parachute sprint","aliases":["Speed chute sprint","Resistance parachute run"],"training_type":"Power","tags":["Cardio","Legs","Power","Speed"],"muscle_group":"Legs","primary_muscles":["Glutes","Hamstrings","Quadriceps"],"secondary_muscles":["Calves","Hip flexors"],"movement_pattern":"Gait","equipment":["Speed parachute"],"req":"parachute","equipment_tier":1,"difficulty":"Intermediate","tracking":"count","unilateral":false,"sets":1,"reps":"6 × 20–30 m","form_cues":["Clip the chute on and start with a strong forward lean.","Sprint hard so the chute opens behind you.","Keep your form tall and relaxed once the chute fills."],"common_mistakes":["Leaning back against the pull","Over-striding"],"regressions":["Acceleration sprint"],"progressions":["Sled sprint"],"safety":"Use only in open space with no wind gusts that could yank you.","video":null,"diagram":"","notes":"No gear id for a speed chute; req is empty."},{"id":"tdrill","name":"T-drill","aliases":["T-test agility drill"],"training_type":"Power","tags":["Agility","Legs","Power","Speed"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes","Adductors"],"secondary_muscles":["Calves","Abductors","Hamstrings"],"movement_pattern":"Locomotion","equipment":["4 cones"],"req":"cones","equipment_tier":1,"difficulty":"Intermediate","tracking":"count","unilateral":false,"sets":1,"reps":"4–6 reps","form_cues":["Sprint forward 10 m to the middle cone.","Shuffle 5 m left, 10 m right, 5 m back to the middle.","Backpedal to the start, staying low throughout."],"common_mistakes":["Crossing feet while shuffling","Standing tall in the shuffle"],"regressions":["Lateral shuffle"],"progressions":["Box drill"],"safety":"Use a flat, non-slip surface.","video":null,"diagram":"","notes":"Cones laid out in a T; no gear id for cones, so req is empty."},{"id":"laddersinglehop","name":"Agility ladder: single-leg hops","aliases":["Single-leg ladder hops","One-foot ladder hops"],"training_type":"Plyometric","tags":["Agility","Balance","Legs","Plyometric","Unilateral"],"muscle_group":"Legs","primary_muscles":["Calves","Quadriceps"],"secondary_muscles":["Glutes","Core"],"movement_pattern":"Jump","equipment":["Agility ladder"],"req":"agilityladder","equipment_tier":1,"difficulty":"Intermediate","tracking":"count","unilateral":true,"sets":3,"reps":"2 lengths / leg","form_cues":["Hop on one foot into each square.","Land softly on the ball of the foot, knee slightly bent.","Keep the hip level and the knee over the toes."],"common_mistakes":["Knee caving on landing","Hopping too far and losing control"],"regressions":["Agility ladder: hopscotch"],"progressions":["Single-leg lateral hop"],"safety":"Lay the ladder flat on a non-slip surface so it cannot slide.","video":null,"diagram":"","notes":"Agility ladder has no gear id, so req is empty; tape on the floor works too."},{"id":"hurdlehop","name":"Hurdle hops","aliases":["Mini hurdle hops","Hurdle jumps"],"training_type":"Plyometric","tags":["Legs","Plyometric","Power"],"muscle_group":"Legs","primary_muscles":["Calves","Quadriceps","Glutes"],"secondary_muscles":["Hamstrings","Core"],"movement_pattern":"Jump","equipment":["Mini hurdles or cones"],"req":"hurdles|cones","equipment_tier":1,"difficulty":"Intermediate","tracking":"count","unilateral":false,"sets":3,"reps":"5–6 hurdles","form_cues":["Line up 4–6 low hurdles about a stride apart.","Jump over each with both feet, tucking knees slightly.","Rebound quickly off each landing, staying tall."],"common_mistakes":["Long, sinking ground contacts","Clipping hurdles by not lifting the knees"],"regressions":["Pogo jumps","Consecutive broad jumps"],"progressions":["Depth jump"],"safety":"Use collapsible hurdles or cones that fall over if clipped.","video":null,"diagram":"","notes":"No gear id for hurdles; req is empty."},{"id":"laddercross","name":"Agility ladder crossover","aliases":["Ladder carioca","Crossover ladder step"],"training_type":"Plyometric","tags":["Agility","Cardio","Legs","Plyometric","Warm-up"],"muscle_group":"Cardio","primary_muscles":["Calves","Hip flexors","Adductors"],"secondary_muscles":["Obliques","Abductors"],"movement_pattern":"Locomotion","equipment":["Agility ladder"],"req":"agilityladder","equipment_tier":1,"difficulty":"Advanced","tracking":"count","unilateral":false,"sets":3,"reps":"4 lengths","form_cues":["Move sideways along the ladder.","Cross the trail foot over into each square, then step out.","Turn the hips, keep the shoulders square."],"common_mistakes":["Turning the whole body","Stepping on rungs"],"regressions":["Carioca"],"progressions":[],"safety":"Lay the ladder flat on a non-slip surface so it cannot slide.","video":null,"diagram":"","notes":"Agility ladder has no gear id, so req is empty; tape on the floor works too."},{"id":"ladderhopscotch","name":"Agility ladder: hopscotch","aliases":["Hopscotch ladder","Ladder in-out hops"],"training_type":"Plyometric","tags":["Agility","Cardio","Legs","Plyometric","Warm-up"],"muscle_group":"Cardio","primary_muscles":["Calves","Quadriceps"],"secondary_muscles":["Glutes","Core"],"movement_pattern":"Jump","equipment":["Agility ladder"],"req":"agilityladder","equipment_tier":1,"difficulty":"Intermediate","tracking":"count","unilateral":false,"sets":3,"reps":"4 lengths","form_cues":["Hop with both feet into a square, then land one foot either side of the next.","Alternate in and out all the way down.","Keep contacts quick and quiet."],"common_mistakes":["Landing heavy on the heels","Losing rhythm halfway"],"regressions":["Agility ladder: two feet in each"],"progressions":["Agility ladder: single-leg hops"],"safety":"Lay the ladder flat on a non-slip surface so it cannot slide.","video":null,"diagram":"","notes":"Agility ladder has no gear id, so req is empty; tape on the floor works too."},{"id":"ladderlateral","name":"Agility ladder: lateral in-in-out-out","aliases":["Lateral in and out","Lateral two-in ladder"],"training_type":"Plyometric","tags":["Agility","Cardio","Legs","Plyometric","Warm-up"],"muscle_group":"Cardio","primary_muscles":["Calves","Abductors","Adductors"],"secondary_muscles":["Quadriceps","Glutes"],"movement_pattern":"Locomotion","equipment":["Agility ladder"],"req":"agilityladder","equipment_tier":1,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":3,"reps":"4 lengths","form_cues":["Face the side of the ladder.","Step in, in, then out, out, moving down one square each time.","Keep your hips low and facing forward."],"common_mistakes":["Crossing the feet","Standing too tall"],"regressions":["Agility ladder: two feet in each"],"progressions":["Icky shuffle"],"safety":"Lay the ladder flat on a non-slip surface so it cannot slide.","video":null,"diagram":"","notes":"Agility ladder has no gear id, so req is empty; tape on the floor works too."},{"id":"ladderone","name":"Agility ladder: one foot in each","aliases":["Quick feet ladder","Ladder run-through","One-in ladder"],"training_type":"Plyometric","tags":["Agility","Cardio","Legs","Plyometric","Warm-up"],"muscle_group":"Cardio","primary_muscles":["Calves","Hip flexors"],"secondary_muscles":["Quadriceps","Core"],"movement_pattern":"Locomotion","equipment":["Agility ladder"],"req":"agilityladder","equipment_tier":1,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":3,"reps":"4 lengths","form_cues":["Run through, placing one foot in each square.","Stay on the balls of your feet, arms pumping.","Speed up only as long as you stay clean."],"common_mistakes":["Stepping on the rungs","Looking straight down the whole time"],"regressions":["Walk-through"],"progressions":["Agility ladder: two feet in each"],"safety":"Lay the ladder flat on a non-slip surface so it cannot slide.","video":null,"diagram":"","notes":"Agility ladder has no gear id, so req is empty; tape on the floor works too."},{"id":"laddertwo","name":"Agility ladder: two feet in each","aliases":["Two-in ladder","Two feet in each square"],"training_type":"Plyometric","tags":["Agility","Cardio","Legs","Plyometric","Warm-up"],"muscle_group":"Cardio","primary_muscles":["Calves","Hip flexors"],"secondary_muscles":["Quadriceps","Core"],"movement_pattern":"Locomotion","equipment":["Agility ladder"],"req":"agilityladder","equipment_tier":1,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":3,"reps":"4 lengths","form_cues":["Step both feet into each square, one after the other.","Keep steps short, light and fast.","Drive arms in rhythm with your feet."],"common_mistakes":["Heavy, flat-footed steps","Rushing and kicking the ladder"],"regressions":["Agility ladder: one foot in each"],"progressions":["Agility ladder: lateral in-in-out-out"],"safety":"Lay the ladder flat on a non-slip surface so it cannot slide.","video":null,"diagram":"","notes":"Agility ladder has no gear id, so req is empty; tape on the floor works too."},{"id":"ickyshuffle","name":"Icky shuffle","aliases":["Ickey shuffle","In-in-out ladder"],"training_type":"Plyometric","tags":["Agility","Cardio","Legs","Plyometric","Warm-up"],"muscle_group":"Cardio","primary_muscles":["Calves","Abductors","Adductors"],"secondary_muscles":["Quadriceps","Hip flexors"],"movement_pattern":"Locomotion","equipment":["Agility ladder"],"req":"agilityladder","equipment_tier":1,"difficulty":"Intermediate","tracking":"count","unilateral":false,"sets":3,"reps":"4 lengths","form_cues":["Step in-in, then out to the side, moving forward each square.","Alternate the outside step from side to side.","Stay light and rhythmic, eyes up."],"common_mistakes":["Losing the in-in-out rhythm","Big slow steps"],"regressions":["Agility ladder: lateral in-in-out-out"],"progressions":["Agility ladder crossover"],"safety":"Lay the ladder flat on a non-slip surface so it cannot slide.","video":null,"diagram":"","notes":"Agility ladder has no gear id, so req is empty; tape on the floor works too."},{"id":"sbload","name":"Sandbag load to platform","aliases":["Sandbag over bar","Sandbag to platform"],"training_type":"Strongman","tags":["Compound","Power","Strongman"],"muscle_group":"Back","primary_muscles":["Glutes","Hamstrings","Lower back"],"secondary_muscles":["Upper back","Biceps"],"movement_pattern":"Hinge","equipment":["Sandbag","Platform or box"],"req":"sandbag","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":4,"reps":"3–5","form_cues":["Lap the bag onto your thighs.","Hug it tight and extend the hips hard.","Drive the bag onto the platform without pressing it."],"common_mistakes":["Using the arms to throw the bag","Standing too far from the platform"],"regressions":["Sandbag clean"],"progressions":["Atlas stone load"],"safety":"Use a stable platform at waist to chest height and keep fingers clear.","video":null,"diagram":"","notes":"Popular in strongman events and medleys."},{"id":"sbshoulder","name":"Sandbag shouldering","aliases":["Sandbag to shoulder"],"training_type":"Strongman","tags":["Compound","Power","Strength","Strongman"],"muscle_group":"Back","primary_muscles":["Glutes","Hamstrings","Upper back"],"secondary_muscles":["Biceps","Core","Traps"],"movement_pattern":"Hinge","equipment":["Sandbag"],"req":"sandbag","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":true,"sets":4,"reps":"3–5 / side","form_cues":["Lap the bag first by squatting and pulling it to your thighs.","Explode hips and pop the bag onto one shoulder.","Stand tall, then lower it under control."],"common_mistakes":["Lifting with the lower back alone","Not alternating shoulders"],"regressions":["Sandbag clean"],"progressions":["Atlas stone load"],"safety":"A rounded back is normal on stone-style lifts but keep it braced; start light.","video":null,"diagram":"","notes":""},{"id":"sandcarry","name":"Sandbag bear-hug carry","aliases":["Sandbag carry"],"training_type":"Strongman","tags":["Compound","Core","Endurance","Strength","Strongman"],"muscle_group":"Core","primary_muscles":["Core","Upper back"],"secondary_muscles":["Biceps","Glutes","Quadriceps"],"movement_pattern":"Carry","equipment":["Sandbag"],"req":"sandbag","equipment_tier":1,"difficulty":"Intermediate","tracking":"cardio","unilateral":false,"sets":3,"reps":"40 m","form_cues":["Hug the bag tight to your chest, hands clasped.","Stand tall and keep your chin over the bag.","Walk with short, quick steps and steady breathing."],"common_mistakes":["Leaning back excessively","Letting the bag slide down"],"regressions":["Kettlebell front rack carry"],"progressions":["Yoke carry"],"safety":"Lift the bag from the floor with a hinge, not a rounded back.","video":null,"diagram":"","notes":""},{"id":"atlas","name":"Atlas stone load","aliases":["Stone to platform","Stone load"],"training_type":"Strongman","tags":["Compound","Power","Strongman"],"muscle_group":"Back","primary_muscles":["Glutes","Hamstrings","Spinal erectors"],"secondary_muscles":["Biceps","Upper back","Quadriceps"],"movement_pattern":"Hinge","equipment":["Atlas stone","Platform"],"req":"atlasstone|sandbag","equipment_tier":3,"difficulty":"Advanced","tracking":"w","unilateral":false,"sets":4,"reps":"2–4","form_cues":["Straddle the stone and wrap your arms deep around it.","Lap it onto your thighs, then re-grip high.","Extend hips explosively to roll it onto the platform."],"common_mistakes":["Pulling with straight legs","Stone too far from the body"],"regressions":["Sandbag load to platform"],"progressions":[],"safety":"Use tacky and forearm sleeves, start light, and keep your feet clear of the drop.","video":null,"diagram":"","notes":"No gear id for stones; req uses sandbag, the closest home substitute."},{"id":"axledl","name":"Axle deadlift","aliases":["Fat bar deadlift"],"training_type":"Strongman","tags":["Back","Compound","Strength","Strongman"],"muscle_group":"Back","primary_muscles":["Glutes","Hamstrings","Forearms"],"secondary_muscles":["Spinal erectors","Traps","Quadriceps"],"movement_pattern":"Hinge","equipment":["Axle bar or barbell with thick grips","Weight plates"],"req":"barbell,plates,fatgrips","equipment_tier":3,"difficulty":"Advanced","tracking":"w","unilateral":false,"sets":3,"reps":"3–5","form_cues":["Set up like a normal deadlift, double overhand grip.","Squeeze the thick bar hard before you pull.","Drive through the floor and lock out tall."],"common_mistakes":["Mixed grip to avoid grip work","Bar drifting away from the shins"],"regressions":["Thick-grip dumbbell hold","Deadlift"],"progressions":[],"safety":"Use a hook or double overhand grip and lower with control; the axle doesn't spin.","video":null,"diagram":"","notes":"Thick grips on a regular barbell mimic an axle."},{"id":"logpress","name":"Log press","aliases":["Log clean and press"],"training_type":"Strongman","tags":["Compound","Power","Shoulders","Strongman"],"muscle_group":"Shoulders","primary_muscles":["Shoulders","Triceps"],"secondary_muscles":["Upper chest","Core","Quadriceps"],"movement_pattern":"Vertical push","equipment":["Strongman log"],"req":"log","equipment_tier":3,"difficulty":"Advanced","tracking":"w","unilateral":false,"sets":4,"reps":"3–5","form_cues":["Clean the log onto your chest, elbows high.","Dip and drive with the legs.","Press through to lockout with the head forward."],"common_mistakes":["Pressing with elbows low","Leaning back on the press"],"regressions":["Sandbag overhead press","Standing barbell overhead press"],"progressions":[],"safety":"Learn the clean light and drop the log in front, never behind you.","video":null,"diagram":"","notes":"No log gear id; req uses barbell as nearest. Neutral grip suits sore shoulders."},{"id":"tyreflip","name":"Tyre flip","aliases":["Tire flip"],"training_type":"Strongman","tags":["Compound","Power","Strongman"],"muscle_group":"Legs","primary_muscles":["Glutes","Hamstrings","Quadriceps"],"secondary_muscles":["Spinal erectors","Chest","Triceps"],"movement_pattern":"Hinge","equipment":["Large tyre"],"req":"tyre","equipment_tier":3,"difficulty":"Advanced","tracking":"w","unilateral":false,"sets":4,"reps":"4–6","form_cues":["Squat down, chest against the tyre, fingers under the tread.","Drive forward and up with the legs, not the arms.","Pop a knee in, flip hands, and push it over."],"common_mistakes":["Deadlifting with a rounded back","Curling the tyre with the arms (biceps tear risk)"],"regressions":["Sandbag load to platform"],"progressions":[],"safety":"Keep arms long (never curl the tyre) and stay clear of where it lands.","video":null,"diagram":"","notes":"No gear id for a tyre; req uses sled as the nearest strongman-area id."},{"id":"yoke","name":"Yoke carry","aliases":["Yoke walk"],"training_type":"Strongman","tags":["Compound","Core","Legs","Strongman"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes","Core"],"secondary_muscles":["Upper back","Calves","Spinal erectors"],"movement_pattern":"Carry","equipment":["Yoke"],"req":"yoke","equipment_tier":3,"difficulty":"Advanced","tracking":"w","unilateral":false,"sets":4,"reps":"20 m","form_cues":["Set under the yoke bar like a back squat.","Brace hard and stand it up.","Take short, fast steps, keeping the yoke level."],"common_mistakes":["Taking long strides that swing the yoke","Losing the brace and folding forward"],"regressions":["Farmer's carry"],"progressions":[],"safety":"Learn with light loads on a flat surface and drop the yoke forward or back if you lose control.","video":null,"diagram":"","notes":"No yoke? A barbell in a rack can be walked out for short distances (bar walk). req uses barbell as nearest gear id."},{"id":"swimbreast","name":"Breaststroke","aliases":["Breaststroke swimming"],"training_type":"Cardio","tags":["Cardio","Endurance","Recovery"],"muscle_group":"Cardio","primary_muscles":["Pectorals","Adductors","Quadriceps"],"secondary_muscles":["Shoulders","Glutes","Latissimus dorsi","Heart and lungs"],"movement_pattern":"Locomotion","equipment":["Swimming pool or open water","Goggles"],"req":"pool","equipment_tier":0,"difficulty":"Beginner","tracking":"cardio","unilateral":false,"sets":1,"reps":"500 m","form_cues":["Pull, breathe, kick, glide—in that order.","Snap your heels round in a whip kick.","Glide with arms extended before the next stroke."],"common_mistakes":["Skipping the glide","Keeping the head up the whole time"],"regressions":[],"progressions":["Freestyle swimming"],"safety":"Breaststroke kick can strain the inner knee; ease in if you have knee issues.","video":null,"diagram":"","notes":"Needs pool access; no app gear id for a pool."},{"id":"swimfree","name":"Freestyle swimming","aliases":["Front crawl","Freestyle"],"training_type":"Cardio","tags":["Cardio","Endurance","Recovery"],"muscle_group":"Cardio","primary_muscles":["Latissimus dorsi","Shoulders"],"secondary_muscles":["Triceps","Core","Glutes","Hip flexors","Heart and lungs"],"movement_pattern":"Locomotion","equipment":["Swimming pool or open water","Goggles"],"req":"pool","equipment_tier":0,"difficulty":"Intermediate","tracking":"cardio","unilateral":false,"sets":1,"reps":"1 km","form_cues":["Keep your head down and body long and flat.","Rotate your body and reach long with each stroke.","Breathe to the side every 2–3 strokes."],"common_mistakes":["Lifting the head to breathe so the legs sink","Kicking from the knees instead of the hips","Crossing hands over the midline"],"regressions":["Kickboard kicks","Breaststroke"],"progressions":["Butterfly"],"safety":"Swim in supervised areas; avoid open water alone.","video":null,"diagram":"","notes":"No app gear id e