e.","Press the hip into the floor."],"common_mistakes":["Arching the back","Knee drifting outward"],"regressions":["Side-lying quad stretch"],"progressions":["Couch stretch"],"safety":"Ease the strap in slowly.","video":null,"diagram":"","notes":""},{"id":"ringpress","name":"Pilates ring chest press","aliases":["Magic circle arm press"],"training_type":"Pilates","tags":["Home-friendly","Pilates","Strength"],"muscle_group":"Chest","primary_muscles":["Pectorals"],"secondary_muscles":["Anterior deltoids","Triceps"],"movement_pattern":"Isolation","equipment":["Pilates ring","Mat"],"req":"pilatesring","equipment_tier":1,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":2,"reps":"12–15","form_cues":["Hold the ring at chest height, palms on the pads.","Squeeze the ring with soft elbows.","Keep shoulders down away from ears."],"common_mistakes":["Shrugging","Locking elbows"],"regressions":[],"progressions":["Overhead ring press"],"safety":"Use light pressure with shoulder pain.","video":null,"diagram":"","notes":""},{"id":"ringbridge","name":"Pilates ring bridge","aliases":["Magic circle bridge"],"training_type":"Pilates","tags":["Glutes","Pilates","Strength"],"muscle_group":"Glutes","primary_muscles":["Glutes","Adductors"],"secondary_muscles":["Hamstrings","Core"],"movement_pattern":"Hinge","equipment":["Pilates ring","Mat"],"req":"pilatesring","equipment_tier":1,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":2,"reps":"10–12","form_cues":["Ring between the knees, feet hip-width.","Roll up into a bridge one bone at a time.","Squeeze the ring at the top, then roll down."],"common_mistakes":["Arching the low back at the top","Losing ring tension"],"regressions":["Glute bridge"],"progressions":["Single-leg ring bridge"],"safety":"Keep the weight off the neck.","video":null,"diagram":"","notes":""},{"id":"pilatesringsq","name":"Pilates ring thigh squeeze","aliases":["Magic circle inner thigh squeeze","Adductor squeeze"],"training_type":"